//! `velarx-cri`: the Kubernetes CRI (runtime.v1) in front of the engine.
//! A wrapper only: everything it does is a call of `engine::Engine`; what
//! the engine cannot do is an error that says so.
#![allow(
    clippy::result_large_err,
    reason = "tonic::Status is the error of every method of a gRPC service and of the helpers that feed them: the type is tonic's"
)]

/// The gRPC code generated from `proto/runtime/v1/api.proto` (Apache-2.0,
/// the Kubernetes Authors).
#[allow(
    clippy::all,
    reason = "generated by tonic-build: not code of velarx to change"
)]
pub mod api {
    tonic::include_proto!("runtime.v1");
}

pub mod engine;
pub mod meta;
pub mod peer;
pub mod service;
pub mod spdy;
pub mod stream;
